import { dockSceneToolbar } from '../ui/scene-toolbar.mjs';
import { surfaceLifecycle } from '../ui/surface-motion.mjs';
import { bindFloatingDrag } from '../ui/floating-window.mjs';
import { patchHtml } from '../phone-v2/dom-patch.mjs';
import { INVENTORY_PAGE_SIZE, inventoryItems } from './model.mjs';
import { COLLECTION_STYLE } from './collection-style.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const TAU=Math.PI*2,ROOM={size:1200,cx:588,cy:588,seatRadius:324,runRadius:468};
export function collectionTrackPosition(turn,lane='items'){
 const angle=turn*TAU,radius=lane==='runner'?ROOM.runRadius:ROOM.seatRadius;
 return{x:ROOM.cx+radius*Math.sin(angle),y:ROOM.cy-radius*Math.cos(angle),angle,facing:Math.cos(angle)>=0?1:-1};
}
export function collectionClockwiseTarget(turn,index){if(!Number.isInteger(index)||index<0||index>=8)throw Error('invalid collection chair');let target=Math.floor(turn)+index/8;if(target<turn-1e-9)target++;return Math.max(turn,target);}
export function createCollectionRunner(initialSlot=0){
 let turn=initialSlot/8,target=turn,phase='seated',radius=ROOM.seatRadius,progress=1,seconds=0,heading=turn*TAU+Math.PI,startRadius=radius,startHeading=heading;
 const shortest=(from,to)=>from+Math.atan2(Math.sin(to-from),Math.cos(to-from));
 function enter(next){phase=next;progress=0;startRadius=radius;startHeading=heading;}
 return{get turn(){return turn;},get target(){return target;},get running(){return phase!=='seated';},get phase(){return phase;},get heading(){return heading;},get position(){const angle=turn*TAU;return{x:ROOM.cx+radius*Math.sin(angle),y:ROOM.cy-radius*Math.cos(angle),angle};},get bob(){return phase==='running'?Math.sin(seconds*24)*2:0;},
 select(index){const next=collectionClockwiseTarget(turn,index);if(phase==='seated'&&Math.abs(next-turn)<1e-9)return target;target=next;if(phase==='seated'||phase==='sitting')enter('standing');return target;},
 step(dt){const elapsed=Math.min(.05,Math.max(0,Number(dt)||0));seconds+=elapsed;if(phase==='standing'||phase==='sitting'){progress=Math.min(1,progress+elapsed/.22);const ease=progress*progress*(3-2*progress),seating=phase==='sitting';radius=startRadius+((seating?ROOM.seatRadius:ROOM.runRadius)-startRadius)*ease;heading=startHeading+(shortest(startHeading,turn*TAU+(seating?Math.PI:Math.PI/2))-startHeading)*ease;if(progress>=1){if(seating)phase='seated';else phase='running';}}
 else if(phase==='running'){turn=Math.min(target,turn+elapsed*.36);radius=ROOM.runRadius;heading=turn*TAU+Math.PI/2;if(target-turn<1e-9)enter('sitting');}return turn;},
 finish(){turn=target;radius=ROOM.seatRadius;heading=turn*TAU+Math.PI;phase='seated';progress=1;},reset(index=0){turn=target=index/8;radius=ROOM.seatRadius;heading=turn*TAU+Math.PI;phase='seated';seconds=0;progress=1;}};
}
function slotStyle(index){const point=collectionTrackPosition(index/8);return '--x:'+point.x/1200*100+'%;--y:'+point.y/1200*100+'%';}
export function mountInventoryCollection(container,{getSnapshot,useItem,deleteItem,onClose,assetUrl,runnerFrames=null,roomImage=null,headImage=null,onSelect=()=>{}}){
 const doc=container.ownerDocument,win=doc.defaultView,root=doc.createElement('section');root.className='collection-window';root.dataset.opening='true';root.setAttribute('role','dialog');root.setAttribute('aria-label','圆桌收藏室');
 const runner=createCollectionRunner(),assetRoot=String(assetUrl??'').replace(/inventory\/[^/]+$/,'');
 const room=roomImage??assetRoot+'inventory/round-room-v2.png',head=headImage??assetRoot+'inventory/lin-an-top-head-v2.png';
 for(const file of [room,head]){const image=new win.Image();image.src=file;}let raf=null,lastTime=null;
 const style=doc.createElement('style');style.textContent=COLLECTION_STYLE;const content=doc.createElement('div');content.style.cssText='display:contents';root.append(style,content);container.append(root);const toolbar=doc.createElement('header');toolbar.className='collection-heading';toolbar.innerHTML='<div><small>PERSONAL COLLECTION</small><h1>随身收藏</h1></div><button data-case-close aria-label="关闭收藏匣">×</button>';root.append(toolbar);const toolbarDock=dockSceneToolbar(doc,toolbar);
 let snapshot={items:[],writable:false,chatId:''},items=[],page=0,selectedName='',destroyed=false,epoch=0,dialog=false,note='',notice='',busy=false,initialized=false,drag=null;
 const pages=()=>Math.max(1,Math.ceil(items.length/INVENTORY_PAGE_SIZE)),visible=()=>items.slice(page*8,page*8+8),selected=()=>items.find(x=>x.name===selectedName);
 const reduced=()=>win.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
 function paintRunner(){const node=content.querySelector('.collection-runner');if(!node)return;const point=runner.position;node.style.left=point.x/1200*100+'%';node.style.top=point.y/1200*100+'%';node.style.setProperty('--head-heading',runner.heading+'rad');node.style.setProperty('--head-bob',runner.bob+'px');node.dataset.running=String(runner.running);node.dataset.phase=runner.phase;root.dataset.runnerTurn=String(runner.turn);root.dataset.runnerTarget=String(runner.target);root.dataset.motionPhase=runner.phase;root.dataset.selectedItem=selectedName;}
 function tick(time){raf=null;if(destroyed||root.dataset.windowClosing)return;runner.step(lastTime===null?0:(time-lastTime)/1000);lastTime=time;paintRunner();if(runner.running)raf=win.requestAnimationFrame(tick);else lastTime=null;}
 function runTo(index){runner.select(index);if(reduced()){runner.finish();if(raf!==null)win.cancelAnimationFrame(raf);raf=null;lastTime=null;}paintRunner();if(runner.running&&raf===null)raf=win.requestAnimationFrame(tick);}
 function choose(name){if(destroyed)return;const index=visible().findIndex(x=>x.name===name);if(index<0)return;selectedName=name;render();runTo(index);onSelect(selected());}
 function render(){if(destroyed||root.dataset.windowClosing)return;const row=selected(),slots=visible();const heading=`<strong>库存</strong><small class="collection-toolbar-meta">圆桌收藏室${snapshot.writable===false?' · 历史楼层只读':''}</small><div class="collection-toolbar-actions"><button data-case-close aria-label="关闭收藏匣">×</button></div>`;
 if(toolbarDock.docked)patchHtml(toolbar,heading);
 patchHtml(content,`<div class="collection-layout" style="translate:${esc(content.querySelector('.collection-layout')?.style.translate||'0px 0px')}">${toolbarDock.docked?'':'<header class="collection-heading">'+heading+'</header>'}<div class="collection-object"><img class="collection-room" src="${esc(room)}" alt="俯视圆形密室，中央圆桌与八把椅子" draggable="false"><div class="collection-slots">${Array.from({length:8},(_,index)=>{const item=slots[index];return `<button class="collection-slot" data-case-slot="${index}" ${item?`data-case-item="${esc(item.name)}" aria-label="选择${esc(item.name)}" aria-pressed="${item.name===selectedName}"`:'disabled aria-label="空槽"'} style="${slotStyle(index)}"><span class="collection-slot-number">${index+1}</span><strong>${esc(item?.name??'空槽')}</strong>${item?`<small>× ${item.count}</small>`:''}</button>`;}).join('')}</div><article class="collection-details" aria-label="选中物品详情"><small>${row?'× '+row.count:'暂无物品'}</small><h2>${esc(row?.name??'空的收藏匣')}</h2><div class="collection-description" tabindex="0">${esc(row?.description||'暂无物品说明。')}</div></article><div class="collection-runner" aria-hidden="true"><img src="${esc(head)}" alt="" draggable="false"></div></div><div class="collection-item-actions"><button class="primary" data-case-use ${!row||busy||snapshot.writable===false?'disabled':''}>使用物品</button><button data-case-discard ${!row||busy||snapshot.writable===false?'disabled':''}>丢弃</button></div><nav class="collection-pager" aria-label="库存分页"><button data-case-page="-1" aria-label="上一页库存" ${pages()<=1?'disabled':''}>‹</button><span>${page+1} / ${pages()} · ${items.length} 种物品</span><button data-case-page="1" aria-label="下一页库存" ${pages()<=1?'disabled':''}>›</button></nav><div class="collection-status" role="status">${esc(notice)}</div></div>${dialog?`<div class="collection-dialog-layer" data-case-dismiss><form class="collection-dialog" data-case-form role="dialog" aria-modal="true" aria-label="使用收藏物品"><h2>使用 ${esc(row?.name)}</h2><p>写下本次使用意图，随日程中的操作交由剧情判定。</p><textarea data-case-note aria-label="使用物品备注" maxlength="140" placeholder="本次打算怎样使用…">${esc(note)}</textarea><div class="collection-actions"><button type="button" data-case-cancel>取消</button><button type="submit" class="primary" ${busy?'disabled':''}>${busy?'正在暂存…':'暂存使用'}</button></div></form></div>`:''}`);paintRunner();if(!initialized){initialized=true;drag=bindFloatingDrag(toolbarDock.docked?toolbar:content.querySelector('.collection-heading'),content.querySelector('.collection-layout'));(toolbarDock.docked?toolbar:content).querySelector('[data-case-close]')?.focus({preventScroll:true});}}
 async function refresh(){const token=++epoch;try{const next=await getSnapshot();if(destroyed||token!==epoch)return;if(JSON.stringify(next)===JSON.stringify(snapshot)&&content.firstChild)return;if(snapshot.chatId&&snapshot.chatId!==next.chatId){selectedName='';page=0;dialog=false;note='';notice='';runner.reset();}snapshot=next;items=inventoryItems(next.items);page=Math.min(page,pages()-1);if(!items.some(x=>x.name===selectedName))selectedName=visible()[0]?.name??'';render();}catch(error){notice=error.message;render();}}
 async function act(kind){const row=selected();if(!row||busy)return;busy=true;render();try{const latest=await getSnapshot();if(snapshot.chatId!==latest.chatId)throw Error('当前聊天已切换，请重新选择物品');if(latest.writable===false)throw Error('历史楼层不能使用或丢弃物品');const fresh=inventoryItems(latest.items).find(x=>x.name===row.name);if(!fresh)throw Error('物品已不在库存中');const result=await(kind==='use'?useItem(fresh,note,latest.chatId):deleteItem(fresh,latest.chatId));if(result?.ok===false)throw Error(result.message||'操作未暂存');dialog=false;notice=result?.message||'操作已暂存';await refresh();}catch(error){notice=error.message;}finally{busy=false;render();}}
 function click(event){if(event.target.hasAttribute('data-case-dismiss')){dialog=false;render();return;}const button=event.target.closest('button');if(!button||button.disabled)return;const d=button.dataset;if('caseClose'in d){onClose();return;}if(d.caseItem){choose(d.caseItem);return;}if(d.casePage){page=(page+Number(d.casePage)+pages())%pages();selectedName=visible()[0]?.name??'';render();runTo(0);return;}if('caseUse'in d){note='';dialog=true;render();content.querySelector('textarea')?.focus({preventScroll:true});return;}if('caseDiscard'in d){void act('discard');return;}if('caseCancel'in d){dialog=false;render();}}
 function submit(event){if(event.target.hasAttribute('data-case-form')){event.preventDefault();void act('use');}}
 function input(event){if(event.target.hasAttribute('data-case-note'))note=event.target.value;}
 function key(event){if(event.key==='Escape'){if(dialog){dialog=false;render();}else onClose();}}
 root.addEventListener('click',click);if(toolbarDock.docked)toolbar.addEventListener('click',click);root.addEventListener('submit',submit);root.addEventListener('input',input);root.addEventListener('keydown',key);const initialRefresh=refresh();const timer=win.setInterval(refresh,5000);const lifecycle=surfaceLifecycle(doc,()=>content.querySelector(".collection-layout"),toolbarDock,()=>{drag?.destroy();destroyed=true;epoch++;if(raf!==null)win.cancelAnimationFrame(raf);win.clearInterval(timer);root.remove();},initialRefresh);lifecycle.ready.then(()=>{delete root.dataset.opening;});return{root,refresh,...lifecycle};
}
